def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Count key outcome types and defection streaks.
    opp_d = 0
    my_d = 0
    cc = 0
    last_opp = None
    opp_run_d = 0
    my_run_d = 0

    for i in range(n):
        a, b = history[i]
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1
        if a == 'C' and b == 'C':
            cc += 1

    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_run_d += 1
        else:
            break

    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_run_d += 1
        else:
            break

    last_my, last_opp = history[-1]
    remaining = 100 - n

    # Clear cooperative partner: preserve cooperation, with careful endgame.
    if opp_d == 0:
        # Exploit a pure cooperator only when the endgame value is realized,
        # but leave enough room to keep collecting CC for as long as possible.
        if remaining <= 3:
            return 'D'
        return 'C'

    # Partner is almost always cooperative; tolerate isolated noise.
    if opp_d * 8 <= n:
        # Punish a short burst, but only briefly, then repair.
        if last_opp == 'D':
            if opp_run_d >= 2 and remaining > 8:
                return 'D'
            if last_my == 'D':
                return 'C'
            return 'D'
        # After mutual cooperation resumes, continue cooperating.
        if my_run_d >= 2 and last_opp == 'C':
            return 'C'
        return 'C'

    # Overwhelmingly defecting partner: defect, with rare probes.
    if opp_d * 3 >= n * 2:
        if remaining <= 0:
            return 'D'
        if last_opp == 'C':
            # Immediate reciprocation can recover a modest amount.
            return 'C'
        # Probe deterministically at sparse intervals to find any cooperation.
        if remaining > 12 and (n + cc + opp_d) % 11 == 0:
            return 'C'
        return 'D'

    # Mixed partner. Use a forgiving, retaliatory, repair-oriented rule.
    # If we are stuck in a long mutual-defection run, make a conciliatory move.
    if opp_run_d >= 3 and my_run_d >= 2:
        # One-sided repair attempt: cooperate, then continue if reciprocated.
        if rng.random() < 0.75:
            return 'C'
        return 'D'

    # If the opponent has just cooperated, reward it strongly.
    if last_opp == 'C':
        if last_my == 'D':
            # If they cooperate despite recent defection from us, return to C.
            if remaining > 6:
                return 'C'
            return 'D'
        # Occasional probing only when cooperation is well-established.
        if remaining > 20 and cc * 2 >= n and rng.random() < 0.04:
            return 'D'
        return 'C'

    # Opponent defected. Defect briefly, then offer repair.
    if last_my == 'C':
        # Retaliate immediately.
        if remaining > 8:
            return 'D'
        return 'D' if opp_d * 2 >= n else 'C'

    # Both defected last round.
    if remaining <= 4:
        return 'D'

    # Try to break the DD loop if opponent has historically been mixed.
    if opp_run_d <= 2 and rng.random() < 0.35:
        return 'C'

    # If we have been over-defecting, make a cooperative move.
    if my_run_d >= 4:
        return 'C'

    return 'D'
